// Extraer y evaluar casos vencidos en awaiting_response
const rawItems = $('Consultar Casos en awaiting_response').all();
let cases = [];

if (rawItems.length === 1 && Array.isArray(rawItems[0].json)) {
  cases = rawItems[0].json;
} else {
  cases = rawItems.map(item => item.json).filter(Boolean);
}

// ===== CONFIGURACIÓN (editar aquí; este n8n no permite leer variables de entorno desde los nodos) =====
const ajustes = $('Ajustes PTD-04').first().json;   // se editan en /admin-configuracion
const MODO_PRUEBA = ajustes.modoPrueba;              // true = el ultimátum va a EMAIL_PRUEBA, nunca a la empresa real
const EMAIL_PRUEBA = ajustes.emailPrueba;
const CANAL = ajustes.canalUltimatum;                // gmail | email_certificado | burofax
const PLAZO_POR_DEFECTO = 14;                        // días, si la categoría no tiene plazo configurado
// ===========================================================================================

const now = new Date();
// Plazo configurable por categoría (system_rules.default_deadline_days); si falta, PTD_DEADLINE_DAYS o 14
const plazoPorDefecto = PLAZO_POR_DEFECTO;
const plazoPorCategoria = {};
for (const r of $('Leer Plazos por Categoría').all().map(i => i.json)) {
  if (r && r.category && Number(r.default_deadline_days) > 0) plazoPorCategoria[r.category] = Number(r.default_deadline_days);
}
const isModoPrueba = MODO_PRUEBA;
const testEmail = EMAIL_PRUEBA;

// Si el webhook manual recibe forceTest=true, permite forzar envío en modo prueba aunque no hayan pasado 10 días
let isForcedTest = false;
try {
  const wb = $('Webhook Manual / Test Inmediato').first().json;
  if (wb && (wb.body?.forceTest === true || wb.query?.forceTest === 'true')) {
    isForcedTest = true;
  }
} catch (e) {}

const expiredList = [];

for (const c of cases) {
  if (!c || !c.id) continue;
  const comms = Array.isArray(c.communications_log) ? c.communications_log : [];

  // 1. Verificar si ya se ha enviado un ultimátum previamente
  const alreadyReminded = comms.some(log => {
    const meta = typeof log.metadata === 'string' ? JSON.parse(log.metadata || '{}') : (log.metadata || {});
    const subject = log.subject || '';
    return meta.isReminder === true || meta.isReminder === 'true' || subject.includes('ULTIMÁTUM') || subject.includes('Segunda Reclamación');
  });

  if (alreadyReminded) {
    continue; // Omitir para evitar duplicidades innecesarias
  }

  // 2. Determinar fecha del primer envío de reclamación
  let sentAt = null;
  let recipientEmail = null;

  const firstClaim = comms.find(log => log.channel === 'email' && log.status === 'sent');
  if (firstClaim) {
    sentAt = new Date(firstClaim.created_at);
    recipientEmail = firstClaim.recipient;
  } else {
    sentAt = new Date(c.claim_sent_at || c.updated_at || c.created_at);
  }

  // Vencimiento: el que se comunicó a la empresa al enviar (PTD-03) o, si no consta, el plazo de la categoría
  const categoria = (Array.isArray(c.claim_intakes) ? c.claim_intakes : [])
    .map(ci => ci && ci.intake_prechecks && ci.intake_prechecks.category).find(Boolean) || '';
  const deadlineDays = plazoPorCategoria[categoria] || plazoPorDefecto;
  const dueAt = c.response_due_at ? new Date(c.response_due_at) : new Date(sentAt.getTime() + deadlineDays * 24 * 60 * 60 * 1000);

  // 3. Determinar destinatario y empresa reclamada
  const party = Array.isArray(c.case_parties) && c.case_parties[0] ? c.case_parties[0] : {};
  const companyName = party.name || 'Empresa Reclamada';
  if (!recipientEmail) {
    recipientEmail = (party.contact_details && party.contact_details.email) ? party.contact_details.email : testEmail;
  }

  if (isModoPrueba) {
    recipientEmail = testEmail;
  }

  // 4. Calcular días transcurridos
  const diffMs = now.getTime() - sentAt.getTime();
  const elapsedDays = Math.max(1, Math.floor(diffMs / (1000 * 60 * 60 * 24)));

  // Disparar si ya venció el plazo O si se ha forzado en prueba
  if (now >= dueAt || isForcedTest) {
    const fechaPrimerEnvio = sentAt.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' });
    const asuntoEmail = (isModoPrueba ? '[PRUEBA] ' : '') + `[ULTIMÁTUM] Segunda Reclamación y Recordatorio de Plazo — Ref. ${c.reference}`;

    const cuerpoHtml = `
<div style="font-family: Arial, sans-serif; max-width: 650px; line-height: 1.6; color: #1e293b; padding: 24px; border: 1px solid #e2e8f0; border-radius: 8px;">
  <div style="background-color: #fee2e2; border-left: 4px solid #ef4444; padding: 14px; margin-bottom: 20px; border-radius: 4px;">
    <strong style="color: #991b1b; font-size: 15px;">SEGUNDA RECLAMACIÓN PREVIA / ULTIMÁTUM EXTRAJUDICIAL</strong><br/>
    <span style="color: #7f1d1d; font-size: 13px;">Vencimiento de plazo legal conferido sin respuesta de la compañía. Trámite previo al ejercicio de acciones judiciales ante los Tribunales.</span>
  </div>

  <p><strong>A la atención del Departamento de Reclamaciones / Asesoría Jurídica de:</strong><br/>${companyName}</p>
  <p><strong>Referencia Expediente:</strong> ${c.reference}</p>
  <p><strong>Importe Reclamado:</strong> ${c.amount || 0} €</p>
  <p><strong>Fecha primer requerimiento formal:</strong> ${fechaPrimerEnvio} (${elapsedDays} días naturales transcurridos sin resolución)</p>

  <hr style="border: 0; border-top: 1px solid #e2e8f0; margin: 20px 0;"/>

  <p>Por medio de la presente, les notificamos formalmente que <strong>ha expirado con creces el plazo extrajudicial concedido</strong> en nuestra reclamación previa remitida en fecha ${fechaPrimerEnvio}, sin que hasta la fecha conste resolución estimatoria ni abono de la indemnización legalmente debida a nuestro representado.</p>

  <p>A fin de evitar mayores costes procesales para su entidad, les conferimos un <strong>plazo improrrogable de 5 días hábiles</strong> a contar desde la recepción de este requerimiento para:</p>
  <ol style="padding-left: 20px;">
    <li style="margin-bottom: 8px;">Proceder al reintegro inmediato del importe adeudado (<strong>${c.amount || 0} €</strong>) en la cuenta del titular.</li>
    <li style="margin-bottom: 8px;">O bien remitir justificante bancario de abono a esta misma dirección de correo.</li>
  </ol>

  <div style="background-color: #f8fafc; border: 1px solid #cbd5e1; padding: 12px; border-radius: 6px; margin: 20px 0;">
    <strong style="color: #0f172a;">ADVERTENCIA LEGAL EXPRESA:</strong><br/>
    <span style="color: #334155; font-size: 13px;">De no atender esta segunda reclamación en el plazo citado, el expediente pasará de forma inmediata a los servicios jurídicos de <strong>PorTusDerechos</strong> para la interposición de la correspondiente <strong>demanda judicial de reclamación de cantidad</strong> ante el Juzgado competente, con expresa condena en costas procesales a su entidad por manifiesta temeridad y mala fe conforme a la Ley de Enjuiciamiento Civil.</span>
  </div>

  <p>Atentamente,</p>
  <p><strong>Departamento Jurídico — PorTusDerechos</strong><br/>
  <span style="font-size: 12px; color: #64748b;">Defensa y Reclamaciones de Consumidores</span></p>
</div>
    `.trim();

    expiredList.push({
      canal: CANAL,
      proveedorUrl: ajustes.proveedorUrl,
      caseId: c.id,
      ownerId: c.owner_id,
      reference: c.reference,
      companyName,
      recipientEmail,
      asuntoEmail,
      cuerpoHtml,
      elapsedDays,
      deadlineDays,
      fechaPrimerEnvio,
      metadata: {
        isReminder: true,
        reminderNumber: 1,
        elapsedDays,
        deadlineDays,
        categoria,
        dueAt: dueAt.toISOString(),
        initialSentAt: sentAt.toISOString()
      }
    });
  }
}

return expiredList.map(item => ({ json: item }));

// Ajustes editables en /admin-configuracion. Sin ajustes legibles: modo prueba (seguro).
const a = {};
for (const i of $input.all()) { const r = i.json; if (r && r.key) a[r.key] = r.value; }
return [{ json: {
  modoPrueba: a.modo_prueba !== false,
  emailPrueba: typeof a.email_prueba === 'string' && a.email_prueba ? a.email_prueba : 'idrabde0@gmail.com',
  canalUltimatum: String(a.canal_ultimatum || 'gmail'),
  proveedorUrl: String(a.proveedor_certificado_url || ''),
  appUrl: String(a.app_url || '').replace(/\/$/, '')
} }];
